  ('st-astralstore', 'u-owner-astralstore', 'astralstore', 'AstralStore', 'OWNER', 'PLATINUM', 'ACTIVE', 'Pemilik AstralStore', 'Spesialis akun Valorant rank tinggi dengan koleksi skin langka. Semua akun milik sendiri, diinspeksi sebelum dijual.', 'from-violet-600/90 to-fuchsia-500/80', 500000, 'HELD', 1, 4.94, 218, 231, 1240, 4.90, 4.90, 5, 'u-admin', '2024-03-01 00:00:00'),
  ('st-nusagame', 'u-owner-nusagame', 'nusagame', 'NusaGame', 'RESELLER', 'VERIFIED', 'ACTIVE', 'Rizky Pratama', 'Reseller store dengan katalog terluas — akun titipan penjual eksternal yang dikurasi dan menjadi tanggung jawab penuh kami.', 'from-sky-600/90 to-cyan-500/80', 500000, 'HELD', 1, 4.87, 395, 412, 2380, 4.80, 4.90, 4.80, 'u-admin', '2023-11-01 00:00:00'),
  ('st-verdantshop', 'u-owner-verdantshop', 'verdantshop', 'VerdantShop', 'OWNER', 'VERIFIED', 'ACTIVE', 'Pemilik VerdantShop', 'Akun Immortal+ pilihan dengan deskripsi detail. Fokus pada akurasi listing dan serah terima yang rapi.', 'from-emerald-600/90 to-teal-500/80', 500000, 'HELD', 1, 4.91, 176, 189, 860, 4.90, 4.80, 4.70, 'u-admin', '2024-06-01 00:00:00'),
  ('st-gudangakun', 'u-owner-gudangakun', 'gudangakun', 'GudangAkun', 'RESELLER', 'PLATINUM', 'ACTIVE', 'Pemilik GudangAkun', 'Toko volume terbesar di valostock.id. Ratusan akun terjual tiap bulan dengan pengiriman cepat.', 'from-amber-500/90 to-orange-500/80', 500000, 'HELD', 1, 4.82, 702, 764, 3150, 4.70, 4.80, 4.90, 'u-admin', '2023-01-01 00:00:00'),
  ('st-skyvault', 'u-owner-skyvault', 'skyvault', 'SkyVault', 'OWNER', 'AUTHORIZED', 'ACTIVE', 'Pemilik SkyVault', 'Toko baru dengan harga kompetitif. Sedang membangun rekam jejak — semua transaksi lewat escrow.', 'from-indigo-600/90 to-blue-500/80', 500000, 'HELD', 1, 4.70, 88, 95, 310, 4.60, 4.70, 4.60, 'u-admin', '2025-02-01 00:00:00'),
