  ('genshin-impact', 'Genshin Impact', 'HoYoverse', 'Open-world action RPG', 'Top-up Genesis Crystal Genshin Impact — proses instan, struk dikirim ke email dan WhatsApp.', 0, 1, 0, 0, 'UID', 'UID 9 digit — lihat di pojok kanan bawah layar game', NULL, 'from-amber-400/80 via-orange-500/70 to-emerald-500/70', 'Genesis Crystal', 3),
