INSERT INTO help_articles (slug, title, category, excerpt, body, popular, sort_order) VALUES
  ('cara-membeli-akun', 'Cara membeli akun game di valostock.id', 'GETTING_STARTED', 'Dari mencari akun sampai serah terima di Rekber Room.', '[{"type":"list","items":["Cari akun lewat pencarian atau halaman game, lalu buka detailnya.","Beli langsung, atau nego dulu lewat tombol Tawar.","Bayar: harga akun + biaya penanganan (maks. 3,5%, min. Rp4.000) + proteksi Rp5.000. Dana ditahan di escrow.","Rekber Room terbuka — toko menyerahkan akun, kamu ganti email/password/2FA dan periksa isinya.","Tekan Selesai. Dana baru diteruskan ke toko setelah konfirmasimu, lalu beri rating."]},{"type":"paragraph","text":"Pembeli tidak perlu KYC. Semua transaksi wajib di dalam platform — transaksi di luar menghilangkan escrow dan seluruh perlindunganmu."}]', 1, 0),
  ('apa-itu-rekber-room', 'Apa itu Rekber Room dan kenapa serah terima harus di sana?', 'GETTING_STARTED', 'Ruang transaksi resmi yang diawasi admin dan tercatat.', '[{"type":"paragraph","text":"Rekber Room adalah ruang serah terima resmi yang terbuka otomatis setelah pembayaranmu terkonfirmasi. Kodenya sama dengan ID katalog (mis. VS001), diawasi admin, dan seluruh percakapan tersimpan sebagai bukti sengketa."},{"type":"paragraph","text":"Chat biasa hanya untuk tanya jawab — dilarang bertransaksi, bertukar email, atau nomor telepon di sana."}]', 0, 1),
  ('cara-membuka-toko', 'Cara membuka toko (KYC + deposit)', 'BECOMING_STORE', 'Verifikasi identitas gratis, deposit Rp500.000, langsung berjualan.', '[{"type":"list","items":["Daftar dengan email aktif, lalu selesaikan verifikasi identitas (Sumsub) — gratis.","Bayar deposit keamanan Rp500.000 (aktivasi ±15 menit) — membuka hak listing.","Isi profil toko dan pilih tipe: Owner Store (akun milik sendiri) atau Reseller Store (akun titipan penjual eksternal).","Setujui Perjanjian Transaksi + Kebijakan Privasi → mulai listing."]},{"type":"paragraph","text":"Deposit adalah jaminan keamanan, bukan biaya layanan — bisa dikembalikan saat toko tutup dengan syarat akun bersih (lihat aturan toko)."}]', 1, 2),
  ('tipe-toko-owner-reseller', 'Perbedaan Owner Store dan Reseller Store', 'BECOMING_STORE', 'Siapa yang bertanggung jawab atas akun yang dijual.', '[{"type":"paragraph","text":"Owner Store menjual akun miliknya sendiri. Reseller Store menjual akun titipan penjual eksternal — dan memikul tanggung jawab penuh atas identitas penjual, keaslian akun, dan kerugian pembeli. Platform hanya mengenal dan menindak toko: pembeli melapor dan menilai toko, bukan penjual eksternalnya."}]', 0, 3),
  ('biaya-di-valostock', 'Rincian biaya: komisi, penanganan, dan proteksi', 'FEES_WITHDRAWAL', 'Tiga biaya sederhana — tanpa biaya posting atau biaya tersembunyi.', '[{"type":"list","items":["Komisi platform 5% dari harga final — dipotong dari toko saat pesanan selesai (Premium: 4,5% / 4%).","Biaya penanganan maks. 3,5% (min. Rp4.000) — dibayar pembeli saat checkout.","Proteksi Rp5.000 per pesanan — dibayar pembeli, jendela dukungan 14/30 hari.","Biaya penarikan toko Rp4.000 (+Rp2.500 pajak antarbank)."]},{"type":"paragraph","text":"Komisi selalu dihitung dari harga final setelah nego, jadi tawar-menawar tidak mengubah aturannya."}]', 1, 4),
  ('penarikan-dana-toko', 'Penarikan dana toko & Account Validation', 'FEES_WITHDRAWAL', 'Nama rekening tujuan harus sama dengan nama KYC.', '[{"type":"paragraph","text":"Dana toko tercatat di saldo toko (escrow → tersedia) dan tidak dipakai untuk operasional platform. Penarikan dikirim lewat Midtrans Iris setelah disetujui admin, dan hanya bisa ke rekening atas nama yang sama dengan identitas KYC (Account Validation). Nama tidak cocok → ditolak; mirip sebagian → ditinjau manual."},{"type":"paragraph","text":"Pencairan tersedia 5 jam setelah akun dinyatakan aman. Biaya penarikan Rp4.000 (+Rp2.500 pajak antarbank)."}]', 0, 5),
  ('aturan-listing-akun', 'Aturan listing: kategori, deskripsi, dan ID katalog VS', 'BEFORE_SALE', 'Satu akun = satu katalog — tidak bisa dijual dua kali.', '[{"type":"paragraph","text":"Setiap listing mendapat ID katalog dari platform (awalan VS, mis. VS001). Satu akun hanya bisa punya satu katalog, sehingga double-sell tidak mungkin terjadi. Tulis deskripsi yang akurat: rank, skin/VP, region, akses email, dan metode serah terima."},{"type":"paragraph","text":"Toko juga bisa menjalankan Account Inspection (login-only, 2FA tetap di penjual) untuk mendapatkan badge Account Checked. Klaim mutlak seperti \\"100% aman\\" dilarang di seluruh platform."}]', 0, 6),
  ('pesanan-selesai-dan-rating', 'Kapan pesanan dianggap selesai dan dana cair ke toko?', 'AFTER_SALE', 'Konfirmasi pembeli, jendela otomatis, dan rilis dana 5 jam.', '[{"type":"paragraph","text":"Pesanan selesai saat pembeli menekan Selesai setelah memeriksa akun, atau otomatis setelah jendela inspeksi berakhir jika pembeli tidak merespons. Dana (dikurangi komisi 5%) masuk ke saldo toko, dan pencairan tersedia 5 jam setelah akun dinyatakan aman."},{"type":"paragraph","text":"Setelah selesai, pembeli memberi rating keseluruhan plus Service Score tiga dimensi: akurasi deskripsi, sikap layanan, dan kecepatan pengiriman."}]', 0, 7),
  ('cara-mengajukan-sengketa', 'Cara mengajukan sengketa (72 jam)', 'DISPUTES', 'Batas waktu, bukti yang dibutuhkan, dan arbitrase final.', '[{"type":"list","items":["Ajukan dalam 72 jam sejak masalah terjadi, lewat halaman pesanan (bukan chat).","Sertakan pernyataan lengkap + bukti: riwayat Rekber Room, tangkapan layar, bukti pengiriman.","Kedua pihak memberi tanggapan sesuai timeline yang bisa dipantau.","Jika tidak tercapai kesepakatan, platform mengarbitrase — keputusan final."]},{"type":"paragraph","text":"Toko yang terbukti bersalah menanggung refund pembeli, bisa ditambah potongan deposit. Klaim palsu dari pembeli menurunkan Buyer Trust Score."}]', 1, 8),
  ('kebijakan-refund-top-up', 'Kebijakan refund top-up', 'TOPUP', 'Refund hanya jika item game tidak masuk — dikembalikan ke Balance.', '[{"type":"list","items":["Top-up yang berhasil (VP/diamond sudah masuk) tidak bisa direfund.","Jika item game tidak masuk ke akunmu, dana dikembalikan ke Balance (BLC) — bukan uang tunai.","Cek status pesananmu kapan saja di halaman Cek Invoice dengan nomor invoice.","Jika ada kendala, tim kami menghubungimu lewat email/WhatsApp yang kamu isi saat memesan."]},{"type":"paragraph","text":"Pastikan UID/ID player yang kamu masukkan benar — kesalahan pengisian UID di luar tanggung jawab platform."}]', 1, 9),
  ('kenapa-balance-tidak-bisa-beli-akun', 'Kenapa Balance tidak bisa dipakai membeli akun?', 'BALANCE', 'Balance bersifat closed-loop: khusus top-up, demi tetap legal.', '[{"type":"paragraph","text":"Balance (BLC) adalah alat pembayaran internal khusus top-up, bukan uang elektronik. Agar tetap seperti itu secara hukum (tanpa lisensi e-money dari Bank Indonesia), Balance harus closed-loop:"},{"type":"list","items":["Hanya bisa dipakai untuk top-up game di valostock.id.","Tidak bisa dipakai membeli akun game.","Tidak bisa dicairkan ke bank atau e-wallet.","Tidak bisa ditransfer ke pengguna lain."]},{"type":"paragraph","text":"Jika batasan ini dilonggarkan, Balance berubah status menjadi uang elektronik yang butuh lisensi — karena itu aturan ini berlaku mutlak. Pembelian akun tetap menggunakan pembayaran reguler lewat escrow."}]', 1, 10),
  ('sanksi-dan-penalti-toko', 'Sanksi bertingkat untuk pelanggaran toko', 'PENALTIES', 'Dari peringatan sampai blacklist perangkat/KYC/bank.', '[{"type":"paragraph","text":"Sanksi menyesuaikan tingkat pelanggaran: peringatan → pembatasan listing → denda dari deposit → suspensi 30 hari → ban permanen → blacklist (perangkat/KYC/bank) → proses hukum. Transaksi di luar platform, pengiriman palsu, dan listing bohong dikenai denda deposit + ban tanpa toleransi."}]', 0, 11),
  ('tips-keamanan-akun', 'Tips keamanan setelah menerima akun', 'SECURITY', 'Langkah pertama yang wajib dilakukan di Rekber Room.', '[{"type":"list","items":["Ganti email akun ke email milikmu sendiri terlebih dahulu.","Ganti password dan aktifkan 2FA milikmu.","Periksa perangkat/sesi yang masih login dan keluarkan semuanya.","Lakukan semua ini sebelum menekan Selesai di Rekber Room."]},{"type":"paragraph","text":"Simpan bukti serah terima. Jika ada percobaan pengambilan kembali akun dalam masa proteksi (14/30 hari), laporkan segera dari halaman pesananmu."}]', 0, 12);
INSERT INTO balance_ledger (user_id, type, amount, balance_after, reference) VALUES
  ('u-nightfall', 'ADJUSTMENT', 100000, 100000, 'SEED-SALDO-AWAL');
